import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1786900517000}`),a={name:`reference/tools.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to “Tools”">​</a></h1><p>Eleven tools, all against the wg-easy v15 REST API. Every payload that comes back from wg-easy carries the untrusted-data marker and the 60 000-character budget described in <a href="/guide/security">Security</a>.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Annotation</th><th>Summary</th></tr></thead><tbody><tr><td><code>list_clients</code></td><td><code>readOnlyHint</code></td><td>All clients, optionally filtered and sorted</td></tr><tr><td><code>get_client</code></td><td><code>readOnlyHint</code></td><td>One client in full</td></tr><tr><td><code>create_client</code></td><td>—</td><td>Create a client</td></tr><tr><td><code>update_client</code></td><td>—</td><td>Change selected fields of a client</td></tr><tr><td><code>enable_client</code></td><td><code>idempotentHint</code></td><td>Let a client connect again</td></tr><tr><td><code>disable_client</code></td><td><code>idempotentHint</code></td><td>Block a client, keeping its config</td></tr><tr><td><code>delete_client</code></td><td><code>destructiveHint</code></td><td>Delete a client — two-step</td></tr><tr><td><code>get_client_config</code></td><td><code>readOnlyHint</code></td><td>The client&#39;s <code>.conf</code> file</td></tr><tr><td><code>get_client_qrcode</code></td><td><code>readOnlyHint</code></td><td>The client config as an SVG QR code</td></tr><tr><td><code>generate_one_time_link</code></td><td>—</td><td>A shareable one-time config download link</td></tr><tr><td><code>get_server_info</code></td><td><code>readOnlyHint</code></td><td>Release, settings and interface config</td></tr></tbody></table><h2 id="list-clients" tabindex="-1">list_clients <a class="header-anchor" href="#list-clients" aria-label="Permalink to “list_clients”">​</a></h2><p>Lists all WireGuard clients with status, addresses and traffic statistics.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>filter</code></td><td>string</td><td>no</td><td>Substring match on the name</td></tr><tr><td><code>sort</code></td><td><code>&#39;asc&#39;</code> | <code>&#39;desc&#39;</code></td><td>no</td><td>Sort by name</td></tr></tbody></table><h2 id="get-client" tabindex="-1">get_client <a class="header-anchor" href="#get-client" aria-label="Permalink to “get_client”">​</a></h2><p>Full details of a single client.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>clientId</code></td><td>positive integer</td><td>yes</td><td>Numeric ID from <code>list_clients</code></td></tr></tbody></table><h2 id="create-client" tabindex="-1">create_client <a class="header-anchor" href="#create-client" aria-label="Permalink to “create_client”">​</a></h2><p>Creates a client. wg-easy generates the keys and IP addresses; the new client ID comes back in the response.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>yes</td><td>Display name</td></tr><tr><td><code>expiresAt</code></td><td>string</td><td>no</td><td>ISO date, e.g. <code>2026-12-31</code>. Omit for no expiry</td></tr></tbody></table><h2 id="update-client" tabindex="-1">update_client <a class="header-anchor" href="#update-client" aria-label="Permalink to “update_client”">​</a></h2><p>Changes only the fields you pass; everything else keeps its current value.</p><div class="info custom-block"><p class="custom-block-title">Why it reads before it writes</p><p>wg-easy&#39;s update endpoint expects the <strong>complete</strong> client object, so this tool fetches the current state and merges your changes into it. Fields outside the schema below — including the <code>preUp</code>/<code>postUp</code>/<code>preDown</code>/<code>postDown</code> shell hooks, which run as root on the wg-easy host — are dropped and can never be set here.</p></div><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>clientId</code></td><td>positive integer</td><td><strong>Required.</strong> Which client</td></tr><tr><td><code>name</code></td><td>string</td><td>New display name</td></tr><tr><td><code>enabled</code></td><td>boolean</td><td>Enable or disable</td></tr><tr><td><code>expiresAt</code></td><td>string | null</td><td>ISO date, or <code>null</code> to remove the expiry</td></tr><tr><td><code>ipv4Address</code></td><td>string</td><td>Client IPv4 address</td></tr><tr><td><code>ipv6Address</code></td><td>string</td><td>Client IPv6 address</td></tr><tr><td><code>allowedIps</code></td><td>string[] | null</td><td>CIDRs routed through the tunnel client-side</td></tr><tr><td><code>serverAllowedIps</code></td><td>string[]</td><td>Extra CIDRs the server routes to this client</td></tr><tr><td><code>dns</code></td><td>string[] | null</td><td>DNS servers, or <code>null</code> for the server default</td></tr><tr><td><code>mtu</code></td><td>integer</td><td>MTU</td></tr><tr><td><code>persistentKeepalive</code></td><td>integer</td><td>Keepalive interval in seconds (<code>0</code> disables it)</td></tr></tbody></table><h2 id="enable-client-disable-client" tabindex="-1">enable_client / disable_client <a class="header-anchor" href="#enable-client-disable-client" aria-label="Permalink to “enable_client / disable_client”">​</a></h2><p>Both take only <code>clientId</code>. A disabled client keeps its configuration and keys but cannot connect, which makes <code>disable_client</code> the reversible alternative to deleting.</p><h2 id="delete-client" tabindex="-1">delete_client <a class="header-anchor" href="#delete-client" aria-label="Permalink to “delete_client”">​</a></h2><p>Permanently deletes a client. <strong>Irreversible</strong> — the peer loses access and its keys cannot be restored.</p><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>clientId</code></td><td>positive integer</td><td>yes</td><td>Which client</td></tr><tr><td><code>confirmToken</code></td><td>string</td><td>no</td><td>Token from the first call. Omit on that call</td></tr></tbody></table><p>The flow:</p><ol><li>Call without <code>confirmToken</code>. The tool checks the client exists and returns an error result carrying a random token, valid <strong>5 minutes</strong>, bound to that client ID.</li><li>Confirm with the user.</li><li>Call again with the exact token. The token is consumed on use.</li></ol><p>A token issued for one client ID will not delete another, and an expired token simply starts the flow over.</p><h2 id="get-client-config" tabindex="-1">get_client_config <a class="header-anchor" href="#get-client-config" aria-label="Permalink to “get_client_config”">​</a></h2><p>Returns the WireGuard <code>.conf</code> file for a client.</p><div class="danger custom-block"><p class="custom-block-title">Contains the private key</p><p>The configuration includes the client&#39;s private key in plain text. It is not redacted — handing a peer its config is the purpose of this tool — so treat the output as a credential.</p></div><h2 id="get-client-qrcode" tabindex="-1">get_client_qrcode <a class="header-anchor" href="#get-client-qrcode" aria-label="Permalink to “get_client_qrcode”">​</a></h2><p>The same configuration as SVG QR code markup, for the WireGuard mobile apps. It encodes the same private key and deserves the same handling.</p><h2 id="generate-one-time-link" tabindex="-1">generate_one_time_link <a class="header-anchor" href="#generate-one-time-link" aria-label="Permalink to “generate_one_time_link”">​</a></h2><p>Generates a link that lets someone download a client configuration <strong>once, without authenticating</strong>, so it can be sent to the end user. Requires <code>WG_ENABLE_ONE_TIME_LINKS</code> on the wg-easy instance.</p><p>Returns the link value and its path (<code>/cnf/&lt;link&gt;</code>). Anyone who has the URL before the intended recipient does gets the config, so share it over a channel you trust.</p><h2 id="get-server-info" tabindex="-1">get_server_info <a class="header-anchor" href="#get-server-info" aria-label="Permalink to “get_server_info”">​</a></h2><p>Aggregates three admin endpoints — release/update status, general settings and the WireGuard interface configuration. Secret fields are <a href="/guide/security#admin-secrets-are-redacted">redacted</a>.</p><p>Takes no arguments. Each section is fetched independently, so one failing endpoint returns an <code>error</code> for that section instead of failing the whole call — <code>/api/information</code> in particular returns <code>HTTP 500</code> when the wg-easy container cannot reach GitHub.</p>`,35)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};